def process_docs_ab(dataset: List[Dict[str, str]]) -> Dataset:
    context: List[str] = []
    As: List[str] = []
    Bs: List[str] = []
    labels: List[str] = []

    global prompts_ab, ab_BL2MP, ab_BAT

    if len(dataset) == 1800:
        # np.random.seed(1234)
        # ab = np.random.choice([True, False], size=1800).tolist()
        ab = ab_BL2MP
    elif len(dataset) == 762:
        # np.random.seed(1234)
        # ab = np.random.choice([True, False], size=764).tolist()
        # ab.pop(257)
        # ab.pop(371)
        ab = ab_BAT
    else:
        np.random.seed(1234)
        ab = np.random.choice([True, False], size=len(dataset)).tolist()

    for prompt in prompts_ab:
        for i, shuffle in enumerate(ab):
            if shuffle:
                b: str = dataset[i]["sentence_good"]
                a: str = dataset[i]["sentence_bad"]
                label: str = "B"
            else:
                a: str = dataset[i]["sentence_good"]
                b: str = dataset[i]["sentence_bad"]
                label: str = "A"
            context.append(prompt)
            As.append(a)
            Bs.append(b)
            labels.append(label)
    return Dataset.from_dict({"context": context, "A": As, "B": Bs, "label": labels})

# Custom sampler
# https://github.com/EleutherAI/lm-evaluation-harness/blob/v0.4.11/lm_eval/api/samplers.py
# Executed for each element
# https://github.com/EleutherAI/lm-evaluation-harness/blob/v0.4.11/lm_eval/api/task.py#L928
class FewshotSampler(ContextSampler):
    def sample(self, n: int, eval_doc: dict[str, Any] | None = None, df: Sequence[dict[str, Any]] | None = None, **kwargs) -> List[Dict[str, str]]:
        assert n == 5, "This sampler is designed to sample 5 examples for fewshot prompting."

        global prompts_ab, cont, fewshot_indices_BL2MP, fewshot_indices_BAT
        # Retrieve all the documents (documents * prompts_ab[0] ... documents * prompts_ab[-1])
        docs: List[Dict[str, str]] = self.fewshot_docs()
        # Get the number of samples
        num_docs: int = len(docs) // len(prompts_ab)

        if num_docs == 1800:
            fewshot_indices = fewshot_indices_BL2MP
        elif num_docs == 762:
            fewshot_indices = fewshot_indices_BAT
        else:
            raise ValueError("Unexpected number of documents. Expected either 1800 or 762.")

        # Determine which prompt in prompts_ab we are currently evaluating based on the global cont counter and the number of documents per prompt. This ensures that we sample the correct fewshot examples corresponding to the current prompt being evaluated.
        group: int = cont // num_docs
        fewshot: List[Dict[str, str]] = []
        for idx in fewshot_indices[group]:
            # Get rid of the document if that's the one we're evaluating and it's already in the fewshot.
            if cont != idx:
                fewshot.append(copy.deepcopy(docs[idx]))
        cont += 1
        return fewshot